const input = $input.first().json;
const source = $('Rank Cluster and Check History').first().json;
const byId = new Map((source.articles || []).map(a => [a.id, a]));
const allowedCategories = new Set(['Cybersecurity','Artificial Intelligence','Cloud & Infrastructure','Policy & Regulation','Technology','Business']);
const clean = v => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
const escapeHtml = v => clean(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const safeLink = v => /^https?:\/\/[^\s<>"']+$/i.test(String(v||'')) ? escapeHtml(v) : '';
const categories = ['Cybersecurity','Artificial Intelligence','Cloud & Infrastructure','Policy & Regulation','Technology','Business'];
const classify = a => { const t = (a.title+' '+a.content).toLowerCase(); if(/ransomware|cyber|breach|vulnerab|malware|phishing|exploit|security|threat/.test(t))return 'Cybersecurity'; if(/artificial intelligence|\bai\b|llm|openai|anthropic|gemini|model|deepmind/.test(t))return 'Artificial Intelligence'; if(/cloud|server|chip|semiconductor|nvidia|infrastructure|datacenter/.test(t))return 'Cloud & Infrastructure'; if(/regulat|legislat|privacy|antitrust|policy|government/.test(t))return 'Policy & Regulation'; if(/market|revenue|acquisition|startup|funding|ipo/.test(t))return 'Business'; return 'Technology'; };
let chosen=[];
const seen=new Set();
for(const s of (input.articles || [])){
 const a=byId.get(s.id);
 if(!a || seen.has(a.id) || typeof s.summary!=='string' || !s.summary.trim())continue;
 seen.add(a.id);
 chosen.push({...a,summary:clean(s.summary),category:allowedCategories.has(s.category)?s.category:classify(a)});
}
const provider = chosen.length ? (input.provider || 'AI') : 'deterministic';
if(!chosen.length) chosen=(source.articles||[]).slice(0,10).map(a=>({...a,summary:clean(a.content||a.title).slice(0,350),category:classify(a)}));
chosen=chosen.slice(0,10);
const date=new Date().toLocaleDateString('en-US',{timeZone:'Europe/Rome',year:'numeric',month:'long',day:'numeric'});
const dateShort=new Date().toLocaleDateString('en-GB',{timeZone:'Europe/Rome',day:'2-digit',month:'short',year:'numeric'});
const count=chosen.length;
const uniqueSources=new Set(chosen.map(a=>a.source)).size;
const sections=categories.map(category=>{
 const stories=chosen.filter(a=>a.category===category);
 if(!stories.length)return '';
 const cards=stories.map(a=>{
  const link=safeLink(a.link),score=Number.isFinite(Number(a.score))?Math.max(0,Math.min(100,Math.round(Number(a.score)))):null;
  const related=(a.relatedSources||[]).filter(s=>safeLink(s.link)).slice(0,3);
  const relatedText=related.length?`<tr><td style="padding:0 0 18px 0;font-size:12px;line-height:19px;color:#64748b">Additional coverage: ${related.map(s=>`<a href="${safeLink(s.link)}" style="color:#2563eb;text-decoration:underline">${escapeHtml(s.source)}</a>`).join(' &nbsp;·&nbsp; ')}</td></tr>`:'';
  return `<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse;border-bottom:1px solid #e8edf3"><tr><td style="padding:21px 0 8px 0"><span style="font-family:Arial,sans-serif;font-size:11px;font-weight:bold;letter-spacing:.5px;text-transform:uppercase;color:#64748b">${escapeHtml(a.source)}</span>${score!==null?`<span style="font-family:Arial,sans-serif;font-size:11px;color:#64748b"> &nbsp;·&nbsp; Relevance ${score}/100</span>`:''}</td></tr><tr><td style="padding:0 0 10px 0;font-family:Arial,sans-serif;font-size:19px;line-height:27px;font-weight:bold;color:#17243b">${link?`<a href="${link}" style="color:#17243b;text-decoration:none">${escapeHtml(a.title)}</a>`:escapeHtml(a.title)}</td></tr><tr><td style="padding:0 0 12px 0;font-family:Arial,sans-serif;font-size:14px;line-height:23px;color:#475569">${escapeHtml(a.summary)}</td></tr><tr><td style="padding:0 0 16px 0;font-family:Arial,sans-serif;font-size:12px;font-weight:bold">${link?`<a href="${link}" style="color:#2563eb;text-decoration:none">Read original article &rarr;</a>`:''}</td></tr>${relatedText}</table>`;
 }).join('');
 return `<tr><td style="padding:26px 32px 0 32px"><table role="presentation" cellpadding="0" cellspacing="0" width="100%"><tr><td style="padding:0 0 7px 0;border-bottom:2px solid #2563eb;font-family:Arial,sans-serif;font-size:13px;letter-spacing:1px;text-transform:uppercase;font-weight:bold;color:#17243b">${escapeHtml(category)} <span style="color:#94a3b8;font-weight:normal">(${stories.length})</span></td></tr><tr><td>${cards}</td></tr></table></td></tr>`;
}).filter(Boolean).join('');
const subject=`Tech & AI Briefing | ${dateShort} | ${count} stories`;
const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>${escapeHtml(subject)}</title></head><body style="margin:0;padding:0;background:#f1f5f9;color:#17243b"><div style="display:none;font-size:1px;color:#f1f5f9;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden">Your daily selection of technology, AI and cybersecurity developments.</div><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse;background:#f1f5f9"><tr><td align="center" style="padding:28px 12px"><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="max-width:660px;border-collapse:collapse;background:#ffffff"><tr><td style="padding:34px 32px 31px 32px;background:#111e35"><div style="font-family:Arial,sans-serif;font-size:11px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#93c5fd">DAILY INTELLIGENCE</div><h1 style="font-family:Arial,sans-serif;margin:12px 0 10px 0;font-size:31px;line-height:38px;letter-spacing:-.6px;color:#ffffff">Tech &amp; AI Briefing</h1><div style="font-family:Arial,sans-serif;font-size:13px;line-height:20px;color:#cbd5e1">${escapeHtml(date)} &nbsp;·&nbsp; Curated technology news</div></td></tr><tr><td style="padding:20px 32px;background:#f8fafc;border-bottom:1px solid #e2e8f0"><table role="presentation" cellpadding="0" cellspacing="0" width="100%"><tr><td width="50%" style="font-family:Arial,sans-serif;font-size:12px;color:#64748b"><strong style="display:block;font-size:24px;line-height:30px;color:#17243b">${count}</strong>Selected stories</td><td width="50%" style="font-family:Arial,sans-serif;font-size:12px;color:#64748b"><strong style="display:block;font-size:24px;line-height:30px;color:#17243b">${uniqueSources}</strong>Primary sources</td></tr></table></td></tr><tr><td style="padding:23px 32px 0 32px;font-family:Arial,sans-serif;font-size:14px;line-height:23px;color:#475569">A concise overview of the latest developments in cybersecurity, artificial intelligence, cloud infrastructure and the technology industry.</td></tr>${sections}<tr><td style="padding:30px 32px 32px 32px"><div style="height:1px;background:#e2e8f0"></div><p style="font-family:Arial,sans-serif;font-size:12px;line-height:20px;color:#64748b;margin:19px 0 0 0">This briefing is automatically curated from publicly available sources. Summaries may contain errors; consult the original articles for verification.</p><p style="font-family:Arial,sans-serif;font-size:11px;line-height:18px;color:#94a3b8;margin:10px 0 0 0">Tech &amp; AI Briefing &nbsp;·&nbsp; ${escapeHtml(dateShort)}</p></td></tr></table></td></tr></table></body></html>`;
return [{json:{subject,html,eventKeys:chosen.map(a=>a.eventKey),metrics:{...source.metrics,selected:count,provider}}}];

const st=$getWorkflowStaticData('global');st.sent??={};const now=Date.now();for(const [k,v] of Object.entries(st.sent))if(now-v>30*86400000)delete st.sent[k];
const norm=s=>String(s||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
const toks=s=>new Set(norm(s).split(' ').filter(x=>x.length>3));
const similarity=(a,b)=>{const A=toks(a),B=toks(b);return A.size&&B.size?[...A].filter(x=>B.has(x)).length/Math.min(A.size,B.size):0};
const raw=$input.all().map(i=>i.json),articles=[],seen=new Set();
for(const a of raw){if(!a.title||!/^https?:\/\//.test(a.link||''))continue;const originalLink=String(a.link||'').trim();const match=originalLink.match(/^https?:\/\/([^\/?#]+)([^#]*)/i);if(!match)continue;const hostname=match[1].toLowerCase().replace(/^www\./,'');const path=(match[2]||'').replace(/([?&])(utm_[^=&]+|fbclid|gclid)=[^&]*/gi,'$1').replace(/[?&]$/,'');const link=originalLink.slice(0,originalLink.indexOf(match[1]))+match[1]+path;if(seen.has(link))continue;seen.add(link);const dt=Date.parse(a.isoDate||a.pubDate||'');if(!Number.isFinite(dt)||dt<now-36*3600000||dt>now+3600000)continue;
const title=String(a.title),content=String(a.contentSnippet||a.content||'').replace(/<[^>]*>/g,' ').slice(0,600),t=norm(title+' '+content);
const score=Math.max(0,Math.min(100,30+Math.round(25*(1-(now-dt)/129600000))+( /cve|ransomware|breach|vulnerab|exploit|malware|phishing/.test(t)?15:0)+(/artificial intelligence|\bai\b|llm|openai|anthropic|gemini/.test(t)?10:0)+(/critical|released|regulation|acquisition|outage|attack|launch/.test(t)?15:0)-(/webinar|sponsored|giveaway|discount|review/.test(t)?25:0)));
articles.push({id:'n'+articles.length,title,content,link,isoDate:new Date(dt).toISOString(),source:hostname,score});}
articles.sort((a,b)=>b.score-a.score||b.isoDate.localeCompare(a.isoDate));const groups=[];
for(const a of articles){const g=groups.find(g=>g.some(b=>similarity(a.title,b.title)>=.72));if(g)g.push(a);else groups.push([a])}
let skipped=0;const eligible=[],domains={};for(const g of groups){g.sort((a,b)=>b.score-a.score);const a=g[0];const key=norm(a.title).split(' ').filter(x=>x.length>3).sort().join(' ');if(Object.keys(st.sent).some(k=>similarity(k,key)>=.75)){skipped++;continue}if((domains[a.source]||0)>=4)continue;domains[a.source]=(domains[a.source]||0)+1;eligible.push({...a,eventKey:key,relatedSources:g.slice(1,4).map(x=>({source:x.source,link:x.link})),clusterSize:g.length});if(eligible.length>=35)break}
return [{json:{articles:eligible,metrics:{collected:raw.length,valid:articles.length,events:groups.length,previouslySent:skipped,eligible:eligible.length}}}];
